        if(r.statusCode()<200||r.statusCode()>=300){String detail=r.body();if(detail.contains("Too many overlapping announcements"))throw new IllegalArgumentException("Đã có 20 thông báo trùng thời gian. Dừng bớt hoặc chọn lịch khác.");if(path.startsWith("/rest/v1/rpc/")){String rpc=path.substring(path.lastIndexOf('/')+1),code="UNKNOWN";try{String parsed=Json.str(Json.obj(Json.parse(detail)),"code");if(parsed.matches("[A-Z0-9]{5,8}"))code=parsed;}catch(Exception ignored){}System.err.println("Supabase RPC "+rpc+" HTTP "+r.statusCode()+" code "+code);if(code.equals("22P02")&&rpc.equals("gunny_admin"))throw new IllegalArgumentException("Supabase không đọc được định dạng dữ liệu quản trị (22P02).");if(code.equals("PGRST202"))throw new IllegalStateException("Supabase chưa nhận API "+rpc+" (PGRST202). Kiểm tra cache, quyền service_role và migration.");if(code.equals("P0002"))throw new IllegalStateException("Không tìm thấy hồ sơ khi gọi "+rpc+" (P0002). Hãy đăng nhập lại; nếu còn lỗi, kiểm tra dữ liệu hồ sơ.");if(code.equals("42501"))throw new IllegalStateException("API "+rpc+" bị từ chối quyền (42501). Kiểm tra quyền service_role trên Supabase.");if(code.equals("42883"))throw new IllegalStateException("API "+rpc+" gọi hàm không tồn tại (42883). Kiểm tra định nghĩa hàm trong Supabase.");if(r.statusCode()==404)throw new IllegalStateException("Supabase trả lỗi khi gọi "+rpc+" (HTTP 404, "+code+"). Cần kiểm tra mã lỗi này trong Render Logs.");}if((detail.contains("PGRST204")||detail.contains("42703"))&&detail.contains("character_chosen"))throw new IllegalStateException("Chạy migration nhân vật 7.2.0 trên Supabase trước.");if(detail.contains("PGRST202")&&(detail.contains("gunny_equip")||detail.contains("gunny_exchange"))||detail.contains("42703")&&(detail.contains("shopping_money")||detail.contains("worn_mask")))throw new IllegalStateException("Chạy migration trang bị 7.1.8 trên Supabase trước.");if(detail.contains("gunny_profiles_name_unique"))throw new IllegalArgumentException("Tên nhân vật đã được sử dụng. Hãy chọn tên khác.");if(detail.contains("Gift exceeds wallet limit"))throw new IllegalArgumentException("Quà làm số dư vượt 999.999. Giảm quà rồi thử lại.");if(path.endsWith("gunny_support_admin")&&detail.contains("Account not found"))throw new IllegalArgumentException("Tài khoản nhận quà không còn tồn tại.");if(detail.contains("Insufficient stones"))throw new IllegalArgumentException("Chưa đủ đá cường hóa.");if(detail.contains("Insufficient shopping money or stone limit"))throw new IllegalArgumentException("Chưa đủ tiền mua sắm hoặc đã đạt giới hạn đá.");if(detail.contains("Forge level changed"))throw new IllegalArgumentException("Cấp rèn đã thay đổi. Mở lại Tiệm rèn để tải cấp mới.");if(detail.contains("Request key payload mismatch")||detail.contains("Reward payload mismatch"))throw new IllegalArgumentException("Yêu cầu cũ đã thay đổi. Tải lại rồi thực hiện thao tác mới.");if(detail.contains("Dungeon level or difficulty locked"))throw new IllegalArgumentException("Phó bản yêu cầu Lv 15 và vượt Thường trước khi vào Khó.");if(detail.contains("Item not owned"))throw new IllegalArgumentException("Chưa sở hữu vật phẩm.");if(detail.contains("PGRST202")&&detail.contains("gunny_checkout")||detail.contains("42703")&&detail.contains("wardrobe"))throw new IllegalStateException("Chạy migration shop 7.1.6 trên Supabase trước khi mua đồ.");if(detail.contains("user_already_exists")||detail.contains("email_exists")||detail.contains("User already registered"))throw new IllegalArgumentException("Tài khoản đã tồn tại. Hãy đăng nhập bằng mật khẩu cũ.");if(detail.contains("email_not_confirmed"))throw new IllegalArgumentException("Tài khoản cũ chưa được chuyển đổi. Liên hệ quản trị viên để giữ nguyên dữ liệu và kích hoạt đăng nhập.");if(detail.contains("Card already taken"))throw new IllegalArgumentException("Thẻ đã được mở. Chọn thẻ khác.");if(detail.contains("Insufficient earned coins"))throw new IllegalArgumentException("Chưa đủ xu để đổi.");if(detail.contains("Shopping wallet limit"))throw new IllegalArgumentException("Ví tiền mua sắm đã đầy.");if(detail.contains("Insufficient coins"))throw new IllegalArgumentException("Chưa đủ tiền mua sắm để mua đồ.");if(detail.contains("email_address_not_authorized")||detail.contains("Error sending confirmation"))throw new IllegalArgumentException("Dịch vụ tài khoản chưa sẵn sàng.");if(r.statusCode()==429)throw new IllegalArgumentException("Dịch vụ đang giới hạn yêu cầu. Thử lại sau.");if(r.statusCode()==400||r.statusCode()==401||r.statusCode()==422)throw new IllegalArgumentException("Tên đăng nhập hoặc mật khẩu không đúng.");throw new IllegalStateException("Dịch vụ tài khoản tạm thời không phản hồi ("+r.statusCode()+").");}
