    int[] tribalDeck(String match)throws Exception{UUID.fromString(match);List<?> rows=(List<?>)request("/rest/v1/gunny_tribal_matches?id=eq."+match+"&select=deck","GET",null,true);List<?> values=(List<?>)Json.obj(rows.get(0)).get("deck");int[] deck=new int[18];for(int i=0;i<18;i++)deck[i]=((Number)values.get(i)).intValue();return deck;}
