    static final class Memory extends CloudStore {
        int[] tribalDeck(String match){return ((int[])tribalStore.matches.get(match).get("deck")).clone();}
        final Map<String,int[]> giftReceipts=new HashMap<>();final Map<String,Integer> giftTypes=new HashMap<>();
        synchronized int[] giftOpen(String id,int type,String key){if(key.isEmpty()||key.length()>120)throw new IllegalArgumentException("Invalid gift key");String receipt=id+":"+key;if(giftReceipts.containsKey(receipt)){if(giftTypes.get(receipt)!=type)throw new IllegalArgumentException("Gift payload mismatch");return giftReceipts.get(receipt).clone();}Profile p=profile(id);int[] result;
         if(type==0){int lv=p.giftLevel;if(lv>70||Progression.level(p.experience)<lv)throw new IllegalArgumentException("Chưa đủ cấp mở hòm Lv "+lv);int stone=50+rewardRandom.nextInt(51),coin=100*lv;p.giftLevel++;p.stones=Math.min(999999,p.stones+stone);p.coins=Math.min(999999,p.coins+coin);result=lv<70?new int[]{0,p.giftLevel,1,coin,2,stone}:new int[]{1,coin,2,stone};}
         else if(type==1){if(p.giftBags<1)throw new IllegalArgumentException("Chưa có túi quà phó bản");p.giftBags--;int stone=20+rewardRandom.nextInt(51);p.craftStones[0]=Math.min(999999,p.craftStones[0]+stone);boolean vip=rewardRandom.nextInt(100)<10;if(vip)p.vipTickets=Math.min(999999,p.vipTickets+1);result=vip?new int[]{3,stone,4,1}:new int[]{3,stone};}
         else if(type==2){if(p.vipTickets<1)throw new IllegalArgumentException("Chưa có thẻ VIP");p.vipTickets--;p.vipUntil=Math.max(System.currentTimeMillis()/1000,p.vipUntil)+86400;result=new int[]{5,1};}
         else throw new IllegalArgumentException("Invalid gift");giftTypes.put(receipt,type);giftReceipts.put(receipt,result);return result.clone();}
        final Map<String,Integer> stoneGrades=new HashMap<>();
        synchronized int[] claimDungeon(String match,String id,int pick,int card,int difficulty){String key=match+":"+id+":"+pick;boolean legacy=rewards780.containsKey(key);int oldStones=profile(id).stones;int[] reward=claim780(match,id,pick,card);Integer grade=stoneGrades.get(key);if(grade==null){grade=legacy?1:StoneDrops.grade(difficulty,rewardRandom.nextInt(100));if(grade>1){Profile p=profile(id);p.stones=oldStones;p.craftStones[grade-2]=Math.min(999999,p.craftStones[grade-2]+reward[2]);}stoneGrades.put(key,grade);}return new int[]{reward[0],reward[1],reward[2],reward[3],grade};}
        final TribalMemory tribalStore=new TribalMemory(this);
        synchronized void testCheat(String id,int action,boolean enabled){Profile p=profile(id);if(action==6){p.testCheats=enabled;if(!enabled)p.testGod=false;return;}if(!p.testCheats)throw new IllegalArgumentException("Cheat disabled");if(action==0){p.stones=999999;Arrays.fill(p.craftStones,999999);p.luckyCharms=p.protectionCharms=999999;}else if(action==1){for(int kind=0;kind<=6;kind++)for(int item=0;item<10;item++)if(ForgeRules.allowed(kind)&&(kind==0?(p.owned&(1<<item))!=0:(p.wardrobe[p.gender*6+kind-1]&(1<<item))!=0))p.forgeLevels[ForgeRules.index(p.gender,kind,item)]=15;}else if(action==2)p.experience=Progression.experienceForLevel(70);else if(action==3){p.shoppingMoney=p.coins=999999;}else if(action==4)p.testGod=enabled;else throw new IllegalArgumentException("Invalid cheat");}
        synchronized Map<String,Object> tribal(String action,Map<String,Object> payload){return tribalStore.apply(action,payload);}
        record Account(byte[] salt,byte[] hash,Profile profile){}
        final Map<String,Account> accounts=new ConcurrentHashMap<>();final Map<String,int[]> rewards=new ConcurrentHashMap<>();final Map<String,Set<String>> participants=new ConcurrentHashMap<>();final Set<String> settled=ConcurrentHashMap.newKeySet();final SecureRandom random=new SecureRandom();
        final boolean fresh;Memory(){this(false);}Memory(boolean clean){super(true);fresh=clean;}
        byte[] hash(String p,byte[] salt)throws Exception{PBEKeySpec spec=new PBEKeySpec(p.toCharArray(),salt,120000,256);try{return SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256").generateSecret(spec).getEncoded();}finally{spec.clearPassword();}}
        synchronized void ensureNameAvailable(String name,String except){for(var account:accounts.values())if(!account.profile.id.equals(except)&&nameKey(account.profile.name).equals(nameKey(name)))throw new IllegalArgumentException("Tên nhân vật đã được sử dụng. Hãy chọn tên khác.");}
        synchronized void register(String email,String password,String name)throws Exception{ensureNameAvailable(name,"");if(accounts.containsKey(email))throw new IllegalArgumentException("Email đã được dùng.");byte[] salt=new byte[16];random.nextBytes(salt);Profile p=new Profile(UUID.randomUUID().toString(),name);if(fresh){p.owned=p.wornMask=0;p.custom=true;Arrays.fill(p.wardrobe,0);}p.publicId=accounts.size()+1001;accounts.put(email,new Account(salt,hash(password,salt),p));}
        Login login(String email,String password)throws Exception{Account a=accounts.get(email);if(a==null||!MessageDigest.isEqual(a.hash,hash(password,a.salt)))throw new IllegalArgumentException("Sai email hoặc mật khẩu.");return new Login(a.profile.id);}
        Profile profile(String id){for(Account a:accounts.values())if(a.profile.id.equals(id))return a.profile;throw new IllegalArgumentException("Không có tài khoản.");}
        final Map<String,String> economyReceipts=new HashMap<>();final Map<String,int[]> rewards780=new HashMap<>();final Random rewardRandom=new Random();
        synchronized Profile economy780(String id,String operation,Map<String,Object> payload,String key){
            if(key==null||!key.matches("[A-Za-z0-9_-]{1,64}"))throw new IllegalArgumentException("Sai mã yêu cầu");String signature=id+":"+operation+":"+new TreeMap<>(payload);String prior=economyReceipts.get(key);
            if(prior!=null){if(!prior.equals(signature))throw new IllegalArgumentException("Request key payload mismatch");return profile(id);}Profile p=profile(id);
            if(operation.equals("buy")){int q=((Number)payload.get("quantity")).intValue();if(q<1||q>1000||p.shoppingMoney<q*80||p.stones>999999-q)throw new IllegalArgumentException("Chưa đủ tiền mua đá");p.shoppingMoney-=q*80;p.stones+=q;}
            else if(operation.equals("forge")){int sex=((Number)payload.get("sex")).intValue(),kind=((Number)payload.get("kind")).intValue(),item=((Number)payload.get("item")).intValue(),rank=((Number)payload.get("rank")).intValue(),progress=((Number)payload.get("progress")).intValue();if(!ForgeRules.allowed(kind))throw new IllegalArgumentException("Chỉ rèn vũ khí, áo, nón và kính");int i=ForgeRules.index(sex,kind,item);
                if(sex!=p.gender||kind==0&&(!ShopCatalog.weapon(item)||(p.owned&(1<<item))==0)||kind>0&&(p.wardrobe[sex*6+kind-1]&(1<<item))==0)throw new IllegalArgumentException("Chưa sở hữu trang bị");
                if(p.forgeLevels[i]!=rank||p.forgeProgress[i]!=progress)throw new IllegalArgumentException("Cấp rèn đã thay đổi");if(rank>=ForgeRules.MAX_RANK||p.stones<=0)throw new IllegalArgumentException("Chưa đủ đá cường hóa");int spend=Math.min(p.stones,ForgeRules.cost(rank)-progress);p.stones-=spend;p.forgeProgress[i]+=spend;if(p.forgeProgress[i]>=ForgeRules.cost(rank)){p.forgeProgress[i]=0;p.forgeLevels[i]++;}
            }else throw new IllegalArgumentException("Sai thao tác");economyReceipts.put(key,signature);return p;
        }
        synchronized Profile crafting(String id,String action,Map<String,Object> payload,String key,int roll){
            if(key==null||!key.matches("[A-Za-z0-9_-]{1,64}"))throw new IllegalArgumentException("Sai mã yêu cầu");
            String signature=id+":"+action+":"+new TreeMap<>(payload);
            String prior=economyReceipts.get("chance:"+key);
            if(prior!=null){if(!prior.equals(signature))throw new IllegalArgumentException("Request key payload mismatch");return profile(id);}
            Profile p=profile(id);
            int quantity=((Number)payload.get("quantity")).intValue();
            if(action.equals("buy")){
                int material=((Number)payload.get("material")).intValue();
                if(material<0||material>6||quantity<1||quantity>1000)throw new IllegalArgumentException("Sai vật liệu");
                int cost=ForgeRules.price(material)*quantity;
                int owned=material==0?p.stones:material<5?p.craftStones[material-1]:material==5?p.luckyCharms:p.protectionCharms;
                if(p.shoppingMoney<cost||owned>999999-quantity)throw new IllegalArgumentException("Chưa đủ tiền hoặc vượt giới hạn");
                p.shoppingMoney-=cost;
                if(material==0)p.stones+=quantity;else if(material<5)p.craftStones[material-1]+=quantity;
                else if(material==5)p.luckyCharms+=quantity;else p.protectionCharms+=quantity;
            }else if(action.equals("forge")){
                int sex=((Number)payload.get("sex")).intValue(),kind=((Number)payload.get("kind")).intValue(),
                    item=((Number)payload.get("item")).intValue(),rank=((Number)payload.get("rank")).intValue(),
                    grade=((Number)payload.get("grade")).intValue();
                boolean lucky=Boolean.TRUE.equals(payload.get("lucky")),protect=Boolean.TRUE.equals(payload.get("protect"));
                int chance=ForgeRules.chance(rank,grade,quantity,lucky);
                int index=ForgeRules.index(sex,kind,item);
                if(sex!=p.gender||!ForgeRules.allowed(kind)||chance==0||roll<0||roll>=10000
                    ||kind==0&&(!ShopCatalog.weapon(item)||(p.owned&(1<<item))==0)
                    ||kind>0&&(p.wardrobe[sex*6+kind-1]&(1<<item))==0)
                    throw new IllegalArgumentException("Sai trang bị");
                if(p.forgeLevels[index]!=rank)throw new IllegalArgumentException("Cấp rèn đã thay đổi");
                int stones=grade==1?p.stones:p.craftStones[grade-2];
                if(stones<quantity||lucky&&p.luckyCharms<1||protect&&p.protectionCharms<1)
                    throw new IllegalArgumentException("Thiếu đá hoặc bùa");
                if(grade==1)p.stones-=quantity;else p.craftStones[grade-2]-=quantity;
                if(lucky)p.luckyCharms--;if(protect)p.protectionCharms--;
                p.forgeLevels[index]=ForgeRules.result(rank,roll<chance,protect);
                p.forgeProgress[index]=0;
            }else throw new IllegalArgumentException("Sai thao tác");
            economyReceipts.put("chance:"+key,signature);
            return p;
        }
        synchronized int[] claim780(String match,String id,int pick,int card){int kind=matchKinds.getOrDefault(match,0);if((kind!=2&&kind!=3&&kind!=4)||pick<0||pick>(kind==4?0:1)||card<0||card>(kind==4?8:17)||!participants.getOrDefault(match,Set.of()).contains(id))throw new IllegalArgumentException("Không có quyền nhận thẻ");String key=match+":"+id+":"+pick;int[] old=rewards780.get(key);if(old!=null){if(old[0]!=card)throw new IllegalArgumentException("Reward payload mismatch");return old.clone();}
            if(pick==1&&!rewards780.containsKey(match+":"+id+":0"))throw new IllegalArgumentException("Chọn thẻ thứ nhất trước");for(var e:rewards780.entrySet())if(e.getKey().startsWith(match+":")&&e.getValue()[0]==card)throw new IllegalArgumentException("Thẻ đã được mở");int coins=0,stones=0;if(kind>=3)stones=10+rewardRandom.nextInt(91);else if(rewardRandom.nextBoolean())stones=1+rewardRandom.nextInt(10);else coins=500+rewardRandom.nextInt(1501);Profile p=profile(id);p.coins=Math.min(999999,p.coins+coins);p.stones=Math.min(999999,p.stones+stones);if(kind>=3){p.luckyCharms=Math.min(999999,p.luckyCharms+1);if(kind==3)p.protectionCharms=Math.min(999999,p.protectionCharms+1);}
            int[] r={card,coins,stones,pick};rewards780.put(key,r);return r.clone();}
        synchronized void finishAntStage(String match,int winner,List<Map<String,Object>> players,int difficulty){if(difficulty<0||difficulty>2||winner<0||winner>2||players.isEmpty()||players.size()>3)throw new IllegalArgumentException("Sai trận phó bản");if(settled.contains(match))return;Set<String> ids=new HashSet<>();for(var row:players){Profile p=profile((String)row.get("id"));if(!ids.add(p.id)||((Number)row.get("team")).intValue()!=0||Progression.level(p.experience)<15||difficulty==2&&!p.dungeonClear)throw new IllegalArgumentException("Chưa đủ điều kiện phó bản");}settled.add(match);matchKinds.put(match,4);participants.put(match,winner==0?ids:Set.of());for(String id:ids){Profile p=profile(id);p.experience=(int)Math.min(Integer.MAX_VALUE,p.experience+(winner==0?300L:100L));if(winner==0){p.wins++;}}}
        synchronized void finishDungeon780(String match,int winner,List<Map<String,Object>> players,int difficulty){if(difficulty<0||difficulty>2||winner<0||winner>2||players.isEmpty()||players.size()>3)throw new IllegalArgumentException("Sai trận phó bản");if(settled.contains(match))return;Set<String> ids=new HashSet<>();for(var row:players){Profile p=profile((String)row.get("id"));if(!ids.add(p.id)||((Number)row.get("team")).intValue()!=0||Progression.level(p.experience)<15||difficulty==2&&!p.dungeonClear)throw new IllegalArgumentException("Chưa đủ điều kiện phó bản");}settled.add(match);matchKinds.put(match,3);participants.put(match,winner==0?ids:Set.of());for(String id:ids){Profile p=profile(id);p.experience=(int)Math.min(Integer.MAX_VALUE,p.experience+(winner==0?300L:100L));if(winner==0){p.wins++;p.giftBags=Math.min(999999,p.giftBags+1);if(difficulty==1)p.dungeonClear=true;}}}
        synchronized Profile appearance(String id,String name,int gender,int skin,boolean custom,int[] look){ensureNameAvailable(name,id);Profile p=profile(id);p.name=name;p.gender=gender;p.skin=skin;p.custom=custom;p.wornMask=custom?125:3;p.look=look.clone();return p;}
        final Map<String,Integer> exchanges=new HashMap<>();
        synchronized Profile equip(String id,int kind,int item){Profile p=profile(id);if(kind<0||kind>6||item< -1||item>9)throw new IllegalArgumentException("Sai trang bị");if(item>=0){if(kind==0&&(!ShopCatalog.weapon(item)||(p.owned&(1<<item))==0)||kind>0&&(p.wardrobe[p.gender*6+kind-1]&(1<<item))==0)throw new IllegalArgumentException("Chưa sở hữu");if(kind==0)p.equipped=item;else if(kind==1)p.skin=item;else p.look[kind-2]=item;}p.wornMask=ItemRules.maskAfter(p.wornMask,kind,item<0);p.custom=(p.wornMask&2)==0;return p;}
        synchronized Profile bagLayout(String id,int[] slots){Profile p=profile(id);validateLayout(p,slots);p.bagLayout=slots.clone();return p;}
        synchronized Profile exchange(String id,int amount,String key){Profile p=profile(id);Integer prior=exchanges.get(id+":"+key);if(prior!=null){if(prior!=amount)throw new IllegalArgumentException("Sai mã đổi xu");return p;}if(amount<=0||amount>9999||p.coins/100<amount||p.shoppingMoney>999999-amount)throw new IllegalArgumentException("Không đủ xu hoặc số lượng không hợp lệ");p.coins-=amount*100;p.shoppingMoney+=amount;exchanges.put(id+":"+key,amount);return p;}
        synchronized Profile appearanceEquipped(String id,String name,int sex,int skin,boolean custom,int[] look,int mask){Profile p=appearance(id,name,sex,skin,custom,look);p.wornMask=mask;p.characterChosen=true;return p;}
        synchronized Profile checkout(String id,int sex,int[] cart){Profile p=profile(id);if(sex!=p.gender)throw new IllegalArgumentException("Sai nhân vật");int total=ShopCatalog.total(sex,cart,p.owned,p.wardrobe);if(p.shoppingMoney<total)throw new IllegalArgumentException("Chưa đủ tiền mua sắm");p.shoppingMoney-=total;p.owned|=cart[0];ShopCatalog.grant(sex,cart,p.wardrobe);return p;}
        synchronized Profile buy(String id,int weapon){Profile p=profile(id);int price=ShopCatalog.price(0,weapon);if((p.owned&(1<<weapon))==0){if(p.shoppingMoney<price)throw new IllegalArgumentException("Không đủ vàng.");p.shoppingMoney-=price;p.owned|=1<<weapon;}p.equipped=weapon;return p;}
        final Map<String,Integer> matchKinds=new HashMap<>();
        int rank(String id){Profile p=profile(id);int higher=0;for(Account a:accounts.values())if(a.profile.wins>p.wins)higher++;return higher+1;}
        synchronized int[] claim(String match,String id,int card,int coins){int kind=matchKinds.getOrDefault(match,0);if(card<0||card>8||coins<(kind==2?500:200)||coins>(kind==2?2000:1000)||!participants.getOrDefault(match,Set.of()).contains(id))throw new IllegalArgumentException("Không có quyền nhận thưởng.");String key=match+":"+id;if(rewards.containsKey(key))return rewards.get(key).clone();for(Map.Entry<String,int[]> e:rewards.entrySet())if(e.getKey().startsWith(match+":")&&e.getValue()[0]==card)throw new IllegalArgumentException("Thẻ đã được mở. Chọn thẻ khác.");Profile p=profile(id);p.coins=Math.min(999999,p.coins+coins);int[] r={card,coins};rewards.put(key,r);return r.clone();}
        synchronized void settle(String match,int winner,List<Map<String,Object>> players){settle(match,winner,players,0);}
        synchronized void settle(String match,int winner,List<Map<String,Object>> players,int kind){if(kind<0||kind>2)throw new IllegalArgumentException("Sai loại trận");if(!settled.add(match))return;matchKinds.put(match,kind);Set<String> ids=new HashSet<>();for(Map<String,Object> p:players)if(Progression.reward(winner,((Number)p.get("team")).intValue(),((Number)p.getOrDefault("damage",0)).intValue()))ids.add((String)p.get("id"));participants.put(match,ids);for(Map<String,Object> player:players){Profile p=profile((String)player.get("id"));boolean won=((Number)player.get("team")).intValue()==winner;p.coins=Math.min(999999,p.coins+(won?(kind==2?1000:500):winner<2&&((Number)player.getOrDefault("damage",0)).intValue()>0?(kind==2?500:250):0));p.experience=(int)Math.min(2147483647L,p.experience+(won?300L:100L));if(won)p.wins++;}}
    }
